    "ram_ddr5_tag": "Τρέχουσα Γενιά",
    "ram_ddr5_desc": "Το σύγχρονο πρότυπο για σύγχρονες πλατφόρμες. Υψηλότερο εύρος ζώνης και on-die ECC. Τα κιτ ξεκινούν συνήθως από 6000+ MT/s για βέλτιστα σημεία επεξεργασίας.",
