    "ram_ddr3_tag": "Παλαιότερη",
    "ram_ddr3_desc": "Βρίσκεται σε παλαιότερες εγκαταστάσεις. Ιδανική για βασική χρήση γραφείου, αλλά αποτελεί εμπόδιο για τις σύγχρονες βαριές απαιτήσεις επεξεργασίας.",
    "ram_ddr2_tag": "Πολύ Παλιά",
    "ram_ddr2_desc": "Εξαιρετικά περιορισμένο εύρος ζώνης και παλιά τυπική αρχιτεκτονική — κατάλληλη μόνο για διατήρηση κλασικού παλαιού υλικού.",
    "storage_tag": "Αποθήκευση",
    "storage_title": "Τύποι Αποθήκευσης",
    "storage_desc": "Το σημείο όπου βρίσκεται το λειτουργικό σας σύστημα καθορίζει πόσο γρήγορος φαίνεται ο υπολογιστής σας. Για τις περισσότερες κατασκευές, ένας NVMe SSD είναι η σωστή επιλογή.",
