    "storage_nvme_desc": "Μονάδες M.2 συνδεδεμένες με PCIe. Οι σύγχρονες γενιές επιτυγχάνουν εξαιρετικές ταχύτητες—ουσιαστικά ακαριαίες για το λειτουργικό σύστημα και τις εφαρμογές.",
    "storage_sata_tag": "Οικονομικό",
    "storage_sata_desc": "Μορφή 2.5\" ή M.2, που περιορίζεται από την παλαιότερη διεπαφή SATA. Τεράστια αναβάθμιση σε σχέση με οποιονδήποτε μηχανικό περιστρεφόμενο δίσκο.",
    "storage_hdd_tag": "Μαζική Αποθήκευση",
    "storage_hdd_desc": "Μηχανικός περιστρεφόμενος δίσκος. Αξεπέραστο κόστος ανά GB για μεγάλα αρχεία και αντίγραφα ασφαλείας — απλώς αποφύγετε την εγκατάσταση του λειτουργικού σας εδώ.",
    "cpu_tag": "Επεξεργαστής",
    "cpu_title": "Τι πρέπει να γνωρίζετε για τις CPU",
    "cpu_desc": "Ο επεξεργαστής είναι ο εγκέφαλος της κατασκευής σας. Η επιλογή εξαρτάται από τον φόρτο εργασίας σας: το gaming ευνοεί την ταχύτητα ρολογιού, η δημιουργική εργασία τον αριθμό των πυρήνων.",
    "cpu_cores_tag": "Αριθμός Πυρήνων",
    "cpu_cores_desc": "Περισσότεροι πυρήνες χειρίζονται περισσότερες εργασίες απρόσκοπτα. Η επεξεργασία βίντεο, οι μηχανολογικές προσομοιώσεις και οι βαριές ρυθμίσεις ροής επφελούνται περισσότερο.",
    "cpu_clock_tag": "Απόδοση",
    "cpu_clock_desc": "Μετριέται σε GHz. Τα υψηλά ρολόγια μεγιστοποιούν τις εργασίες ενός νήματος. Οι σύντομες συχνότητες αιχμής αντιμετωπίζονται από ενσωματωμένα βήματα boost.",
    "cpu_arch_tag": "Γενιά",
    "cpu_arch_desc": "Οι αυξήσεις του IPC σημαίνουν ότι οι νεότερες αρχιτεκτονικές σε ίδιους ρυθμούς ρολογιού θα ξεπεράσουν αξιόπιστα τις παλαιότερες εκδόσεις.",
    "cpu_tdp_tag": "Θερμικά",
    "cpu_tdp_desc": "Το Thermal Design Power καθοδηγεί την επιλογή των θερμικών λύσεων. Οι υψηλές αποδόσεις ισχύος απαιτούν αποτελεσματικά, στιβαρά συστήματα ψύξης.",
    "gpu_tag": "Γραφικά",
    "gpu_title": "Κάρτες Γραφικών",
    "gpu_desc": "Η GPU είναι το πιο σημαντικό εξάρτημα για παιχνίδια και οπτικούς φόρτους εργασίας. Αποδίδει κάθε καρέ που βλέπετε στην οθόνη.",
    "gpu_vram_tag": "VRAM",
    "gpu_vram_desc": "Η VRAM διατηρεί υφές επεξεργασίας. Οι σύγχρονες εφαρμογές και αναλύσεις κλιμακώνονται επιθετικά, καθιστώντας τις βασικές χωρητικότητες εξαιρετικά σημαντικές.",
    "gpu_upscale_tag": "Upscaling",
    "gpu_upscale_desc": "Οι έξυπνες μηχανές κλιμάκωσης επιτρέπουν στο υλικό γραφικών να υπολογίζει διαμορφώσεις σε χαμηλότερες διαστάσεις και να εμφανίζει υψηλότερους δυναμικούς στόχους.",
    "gpu_ray_tag": "Ray Tracing",
    "gpu_ray_desc": "Προσομοιώνει τις δομικές φυσικές διαδρομές των ακτίνων φωτός. Όμορφες αλλά απαιτητικές υπολογιστικά εργασίες που απαιτούν πυρήνες με επιτάχυνση υλικού.",
    "gpu_pwr_tag": "Κατανάλωση",
    "gpu_pwr_desc": "Οι ισχυροί επιταχυντές γραφικών τραβούν τεράστια λειτουργικά φορτία. Προϋπολογίστε τη χωρητικότητα των γραμμών με περιθώρια ασφαλείας.",
    "psu_tag_top": "Υποδομή",
    "psu_title": "Τροφοδοσία & Ψύξη",
    "psu_desc": "Τα θεμέλια ενός σταθερού συστήματος. Η ποιοτική καθαρή παροχή και η σωστή απαγωγή θερμότητας εξασφαλίζουν μεγάλους κύκλους ζωής του υλικού.",
    "psu_efficiency_tag": "Απόδοση",
    "psu_efficiency_desc": "Οι πιστοποιήσεις 80 Plus (Bronze, Gold, Platinum) αντιπροσωπεύουν την καθαρή απόδοση μετασχηματισμού. Η υψηλή πιστοποίηση μεταφράζεται σε λιγότερη παραγωγή θερμότητας.",
