    "about_hero_eyebrow": "Ποιοι ειμαστε",
    "about_hero_title": "Ένας άνθρωπος.<br>Πολλά κομμάτια hardware.",
    "about_hero_desc": "Το betterPC είναι ένα аτομικό project που γεννήθηκε από μια απλή απογοήτευση: <strong>πάρα πολλοί άνθρωποι πληρώνουν υπερβολικά ποσά για υπολογιστές που δεν καταλαβαίνουν</strong>, ή πετάνε απόλυта λειτουργικό παλιό hardware επειδή κανείς δεν τους είπε ότι μπορεί να αποδώσει μια χαρά.<br><br>Είτε χτίζετε ένα ολοκαίνουργιο gaming rig είτε ανασταίνετε ένα μηχάνημα DDR2 για τον παππού και τη γιαγιά, αυτό το site σας καλύπτει.",
    "about_avatar_name": "Ο Δημιουργός",
    "about_avatar_role": "Ιδρυτής · <span style='color: white;'>better</span><span style='color: #ff7a00;'>PC</span>",
    "about_avatar_bio": "Λάτρης των PC, tinkerer και ανακυκλωτής παλιού υλικού. Έχω στήσει τα πάντα: από οικονομικά DDR2 κουτιά γραφείου μέχρι υδρόψυκτα gaming θηρία — και πιστεύω ότι όλοι αξίζουν να ξέρουν τι κρύβεται μέσα στο μηχάνημά τους.",
    "about_story_eyebrow": "Η ιστορια",
    "about_story_title": "Γιατι υπαρχει το better<span style='color: #ff7a00;'>PC</span>",
    "about_story_h1": "Το πρόβλημα με το παλιό hardware",
    "about_story_p1": "Η Ελλάδα έχει εκατομμύρια PC της περιόδου 2006–2015 ξεχασμένα σε αποθήκες...",
    "about_story_h2": "Ο διαμορφωτής συστήματος",
    "about_story_p2": "Κανένας άλλος ελληνικός οδηγός PC δεν καλύπτει πλαтφόρμες DDR2 και DDR3...",
    "about_story_h3": "Φτιαγμένο για την ελληνική αγορά",
    "about_story_p3": "Οι τιμές περιλαμβάνουν 24% ΦΠΑ και αντικαтоπτρίζουν τι θα πληρώσετε πραγματικά εδώ...",
    "about_story_h4": "Απλή γλώσσα, ουσιαστική γνώση",
    "about_story_p4": "Καμία οроλογία χωρίς επεξήγηση. Κάθε οδηγός σε αυτόν τον ιστότοπο είναι γραμμένος...",
    "about_values_eyebrow": "Αρχες",
    "about_values_title": "Τι πρεσβευει το better<span style='color: #ff7a00;'>PC</span>",
    "about_v1_title": "Ειλικρινείς τιμές",
    "about_v1_desc": "Οι τιμές είναι εκτιμήσεις και επισημαίνονται ως τέτοιες. Όχι φουσκωμένα νούμεра απλά για να φαίνονται οι συνθέσεις φθηνές.",
    "about_v2_title": "Χωρίς διαφημίσεις ή affiliates",
    "about_v2_desc": "Το betterPC δεν κερδίζει τίποта από την πρόταση συγκεκριμένων εταιρειών. Οι επιλογές βασίζονται στην αξία και τη διαθεσιμότητα.",
    "about_v3_title": "Το παλιό hardware έχει αξία",
    "about_v3_desc": "Τα μηχανήματα DDR2 και DDR3 μπορούν ακόμα να εξυπηρετήσουν πραγματικές ανάγκες. Αξίζει να βοηθάμε τον κόσмо να τους δώσει ζωή.",
    "about_v4_title": "Προτεραιότητα στη συμβατότητα",
    "about_v4_desc": "Τίποта δεν προтеίνεται χωρίς έλεγχο. Η συμβατότητα CPU–μητρικής–RAM ελέγχεται προτού σπαταλήσετε χρήματα.",
    "about_v5_title": "Ελληνική πραγματικότητα",
    "about_v5_desc": "Οι τιμές, η διαθεσιμότητα και οι συμβουλές εξαρτημάτων βασίζονται στην ελληνική και ευρύτερη ευρωπαϊκή αγορά, όχι των ΗΠΑ.",
    "about_v6_title": "Συνεχής βелτίωση",
    "about_v6_desc": "Οι λίστες ανταλλακτικών, οι τιμές και οι οδηγοί ενημερώνονται καθώς αλλάζει η αγορά. Δεν είναι ένα παρατημένο site.",
    "about_cta_title": "Είστε έτοιμοι για το στήσιμο;",
    "about_cta_desc": "Χρησιμοποιήστε τον διαμορφωτή για να υπολογίσετε το κόστος του επόμενου PC σας — καινούργιο, οικονομικό ή legacy.",
    "about_cta_btn_primary": "🛠️ Άνοιγμα Διαμορφωτή PC",
    "services_eyebrow": "Υπηρεσίες",
    "services_title": "Βοήθεια με τον υπολογιστή σας, από κάποιον που ξέρει τι κάνει.",
    "services_desc": "Format, καθαρισμός, αναβαθμίσεις — χωρίς ταλαιπωρία, στην περιοχή σας.",
    "services_s1_title": "Καθαρισμός Υπολογιστή",
    "services_s1_desc": "Αφαίρεση σκόνης, αντικατάσταση θερμοαγώγιμης πάστας, εσωτερικός καθαρισμός.",
    "services_s2_title": "Format & Εγκατάσταση Windows",
    "services_s2_desc": "Καθαρή εγκατάσταση, drivers, βασικά προγράμματα έτοιμα για χρήση.",
    "services_s3_title": "Αναβαθμίσεις Hardware",
    "services_s3_desc": "RAM, SSD, κάρτα γραφικών — ό,τι χρειάζεται ο υπολογιστής σας.",
    "services_s4_title": "Αργός Υπολογιστής;",
    "services_s4_desc": "Διάγνωση και βελτίωση απόδοσης.",
    "services_s5_title": "Συναρμολόγηση PC",
    "services_s5_desc": "Βοήθεια στην επιλογή εξαρτημάτων και πλήρης συναρμολόγηση από το μηδέν.",
    "services_price_note": "💬 Οι τιμές εξαρτώνται από τη δουλειά — στείλτε μου μήνυμα για εκτίμηση πριν ξεκινήσουμε οτιδήποτε.",
    "services_area": "📍 Εξυπηρετώ την περιοχή Χαϊδάρι και το ευρύτερο λεκανοπέδιο της Αθήνας. Επίσκεψη στο σπίτι ή φέρτε τον υπολογιστή σας — ό,τι σας βολεύει.",
    "services_about_title": "Ποιος είμαι",
    "services_about_desc": "Ασχολούμαι με hardware υπολογιστών, φτιάχνω συστήματα και μου αρέσει να βοηθάω τον κόσμο να λύσει τα προβλήματά του χωρίς να ξοδεύει μια περιουσία σε κατάστημα. Αν κάτι δεν λειτουργεί σωστά, ας το λύσουμε μαζί."
