    "about_hero_eyebrow": "Wer wir sind",
    "about_hero_title": "Eine Person.<br>Viele PCs.",
    "about_hero_desc": "betterPC ist ein Ein-Personen-Projekt, das aus einer einfachen Frustration heraus entstanden ist: <strong>Zu viele Menschen zahlen zu viel für PCs, die sie nicht verstehen</strong>, oder werfen perfekt funktionierende alte Hardware weg, weil ihnen niemand gesagt hat, dass sie noch einwandfrei laufen würde.<br><br>Egal, ob Sie einen brandneuen Gaming-Rig bauen oder eine DDR2-Maschine für die Großeltern retten, diese Website hilft Ihnen weiter.",
    "about_avatar_name": "Der Ersteller",
    "about_avatar_role": "Gründer · <span style='color: white;'>better</span><span style='color: #ff7a00;'>PC</span>",
    "about_avatar_bio": "PC-Enthusiast, Bastler und Recycler alter Hardware. Ich habe alles gebaut, von günstigen DDR2-Büroboxen bis hin zu wassergekühlten Gaming-Rigs – und ich finde, jeder sollte wissen, was in seiner Maschine steckt.",
    "about_story_eyebrow": "Die Geschichte",
    "about_story_title": "Warum es better<span style='color: #ff7a00;'>PC</span> gibt",
    "about_story_h1": "Das Problem mit alter Hardware",
    "about_story_p1": "Griechenland hat Millionen von PCs aus den Jahren 2006–2015 ungenutzt in Lagern liegen...",
    "about_story_h2": "Der Build-Konfigurator",
    "about_story_p2": "Kein anderer griechischer PC-Leitfaden deckt DDR2- und DDR3-Plattformen ab...",
    "about_story_h3": "Für den griechischen Markt gemacht",
    "about_story_p3": "Die Preise enthalten 24% griechische MwSt. und entsprechen dem, was Sie vor Ort zahlen...",
    "about_story_h4": "Klare Sprache, echtes Wissen",
    "about_story_p4": "Kein Fachjargon ohne Erklärung. Jeder Leitfaden auf dieser Website ist so geschrieben...",
    "about_values_eyebrow": "Prinzipien",
    "about_values_title": "Wofür better<span style='color: #ff7a00;'>PC</span> steht",
    "about_v1_title": "Ehrliche Preise",
    "about_v1_desc": "Preise sind Schätzungen und als solche gekennzeichnet. Keine künstlich niedrigen Zahlen, um Builds billig wirken zu lassen.",
    "about_v2_title": "Keine Werbung, keine Affiliates",
    "about_v2_desc": "betterPC verdient nichts an Empfehlungen bestimmter Marken. Die Auswahl basiert auf Nutzen und Verfügbarkeit.",
    "about_v3_title": "Alte Hardware zählt",
    "about_v3_desc": "DDR2- und DDR3-Systeme können immer noch nützliche Dienste leisten. Es lohnt sich, ihnen neues Leben einzuhauchen.",
    "about_v4_title": "Kompatibilität zuerst",
    "about_v4_desc": "Nichts wird ohne Prüfung empfohlen. Die CPU-Mainboard-RAM-Kompatibilität wird geprüft, bevor Sie Geld verschwenden.",
    "about_v5_title": "Griechischer Kontext",
    "about_v5_desc": "Preise, Verfügbarkeit und Ratschläge basieren auf dem griechischen und EU-Markt, not auf den USA.",
    "about_v6_title": "Ständige Verbesserung",
    "about_v6_desc": "Teilelisten, Preise und Leitfäden werden aktualisiert, wenn sich der Markt ändert. Keine verwaiste Seite.",
    "about_cta_title": "Bereit zum Bauen?",
    "about_cta_desc": "Nutzen Sie den Konfigurator, um Ihren nächsten PC zu planen – brandneu, Budget oder klassisches Legacy-System.",
    "about_cta_btn_primary": "🛠️ PC-Konfigurator öffnen",
    "services_eyebrow": "Dienstleistungen",
    "services_title": "PC-Hilfe von jemandem, der weiß, was er tut.",
    "services_desc": "Formatierung, Reinigung, Upgrades — unkompliziert, in Ihrer Nähe.",
    "services_s1_title": "Computerreinigung",
    "services_s1_desc": "Staubentfernung, Wärmeleitpasten-Wechsel, Innenreinigung.",
    "services_s2_title": "Formatierung & Windows-Installation",
    "services_s2_desc": "Saubere Installation, Treiber, wichtige Programme einsatzbereit.",
    "services_s3_title": "Hardware-Upgrades",
    "services_s3_desc": "RAM, SSD, Grafikkarte — was Ihr PC auch braucht.",
    "services_s4_title": "Langsamer Computer?",
    "services_s4_desc": "Diagnose und Leistungssteigerung.",
    "services_s5_title": "PC-Zusammenbau",
    "services_s5_desc": "Hilfe bei der Teileauswahl und komplette Montage von Grund auf.",
    "services_price_note": "💬 Die Preise hängen vom Auftrag ab — schreiben Sie mir für ein Angebot, bevor wir beginnen.",
    "services_area": "📍 Ich bin im Gebiet Haidari und im Großraum Athen tätig.. Hausbesuch oder Abgabe Ihres PCs — was Ihnen lieber ist.",
    "services_about_title": "Wer ich bin",
