    "hero_tagline": "Configurez mieux. Soyez meilleur.",
    "hero_desc": "Tout ce que vous devez savoir sur le matériel informatique — exploré, comparé et expliqué pour concevoir en toute confiance.",
    "hero_link": "Qui sommes-nous ?",
    "formats_tag": "Facteur de forme",
    "formats_title": "Formats de Cartes Mères",
    "formats_desc": "La carte mère détermine les composants compatibles. Les grandes cartes offrent plus d'extensions ; les petites économisent de l'espace.",
    "formats_atx_tag": "Taille Complète",
    "formats_atx_desc": "Le standard pour la plupart des PC de bureau. Nombreux slots PCIe, emplacements RAM et évolutivité garantie.",
    "formats_matx_tag": "Taille Moyenne",
    "formats_matx_desc": "Un choix équilibré. Légèrement plus petite que l'ATX, elle supporte la plupart des CPU et extensions à un prix inférieur.",
    "formats_itx_tag": "Compacte",
    "formats_itx_desc": "Format miniature pour boîtiers SFF. Limitée à un slot PCIe et deux barrettes RAM — mais impressionnante d'efficacité.",
    "formats_eatx_tag": "Enthousiaste",
    "formats_eatx_desc": "ATX étendu pour stations de travail et plateformes HEDT. Extension maximale, support double CPU sur certaines cartes.",
    "meta_size": "Taille",
    "meta_voltage": "Tension",
    "meta_speed": "Vitesse max",
    "ram_tag": "Mémoire",
    "ram_title": "Générations de RAM",
    "ram_desc": "La vitesse et la capacité de la mémoire système impactent le multitâche, la création et le taux de rafraîchissement en jeu.",
    "ram_ddr5_tag": "Gen Actuelle",
    "ram_ddr5_desc": "Le standard moderne pour les nouvelles plateformes. Bande passante accrue et ECC intégré. Les kits débutent généralement à 6000+ MT/s pour des performances optimales.",
    "ram_ddr4_tag": "Gen Précédente",
    "ram_ddr4_desc": "Encore très répandue. Abordable, largement compatible avec les configurations plus anciennes ou économiques. Le compromis idéal : 16–32 Go à 3200–3600 MHz.",
    "ram_ddr3_tag": "Ancienne",
    "ram_ddr3_desc": "Présente dans les configurations historiques. Convient pour la bureautique de base, mais bride les applications modernes gourmandes.",
    "ram_ddr2_tag": "Obsolète",
    "ram_ddr2_desc": "Bande passante sévèrement limitée et architecture dépassée — uniquement utile pour la préservation de vieux composants.",
    "storage_tag": "Stockage",
    "storage_title": "Types de Stockage",
    "storage_desc": "L'emplacement de votre OS définit la réactivité de votre PC. Pour la plupart, un SSD NVMe pour le disque principal est indispensable.",
    "storage_nvme_tag": "Recommandé",
    "storage_nvme_desc": "Disques M.2 connectés en PCIe. Les générations modernes atteignent des vitesses exceptionnelles — démarrage instantané de l'OS et des apps.",
    "storage_sata_tag": "Économique",
    "storage_sata_desc": "Format 2.5\" ou M.2, limité par l'ancienne interface SATA. Une mise à niveau massive par rapport à n'importe quel disque mécanique.",
    "storage_hdd_tag": "Stockage de Masse",
    "storage_hdd_desc": "Disque dur mécanique. Coût au Go imbattable pour les fichiers volumineux et sauvegardes — évitez d'y installer votre OS principal.",
    "cpu_tag": "Processeur",
    "cpu_title": "Comprendre les CPU",
    "cpu_desc": "Le processeur est le cerveau de votre configuration. Votre choix dépend de vos besoins : les jeux aiment la fréquence, la création aime le nombre de cœurs.",
    "cpu_cores_tag": "Nombre de Cœurs",
    "cpu_cores_desc": "Plus de cœurs gèrent plus de tâches simultanément. Le montage vidéo, les simulations et le streaming en profitent pleinement.",
    "cpu_clock_tag": "Performance",
    "cpu_clock_desc": "Mesuré en GHz. Les hautes fréquences maximisent le mono-thread. Les pics de charge courts sont gérés par les modes boost intégrés.",
    "cpu_arch_tag": "Génération",
    "cpu_arch_desc": "Les gains d'IPC signifient qu'une architecture récente surpassera un ancien modèle même à fréquence égale.",
    "cpu_tdp_tag": "Thermique",
    "cpu_tdp_desc": "Le TDP (Thermal Design Power) guide le choix du refroidissement. Une forte puissance requiert des blocs de dissipation performants.",
    "gpu_tag": "Graphismes",
    "gpu_title": "Cartes Graphiques",
    "gpu_desc": "Le GPU est l'élément le plus important pour le jeu et la création visuelle. Il calcule chaque image affichée à l'écran.",
    "gpu_vram_tag": "VRAM",
    "gpu_vram_desc": "La VRAM stocke les textures. Les applications modernes et les hautes résolutions en consomment beaucoup, rendant sa capacité critique.",
    "gpu_upscale_tag": "Upscaling",
    "gpu_upscale_desc": "Les moteurs de mise à l'échelle intelligents permettent de calculer les images en résolution inférieure avant de les afficher en haute qualité.",
    "gpu_ray_tag": "Ray Tracing",
    "gpu_ray_desc": "Simule le comportement physique de la lumière. Des calculs somptueux mais gourmands exigeant des cœurs dédiés.",
    "gpu_pwr_tag": "Consommation",
    "gpu_pwr_desc": "Les accélérateurs graphiques consomment énormément. Prévoyez une alimentation avec une marge de sécurité confortable.",
    "psu_tag_top": "Infrastructure",
    "psu_title": "Alimentation & Refroidissement",
    "psu_desc": "La base d'un système stable. Une alimentation propre et une bonne dissipation thermique garantissent la longévité de vos composants.",
    "psu_efficiency_tag": "Efficacité",
    "psu_efficiency_desc": "Les certifications 80 Plus (Bronze, Gold, Platinum) indiquent l'efficacité de conversion. Plus elle est haute, moins l'alimentation dégage de chaleur.",
    "psu_modularity_tag": "Modularité",
    "psu_modularity_desc": "Les blocs modulaires permettent de brancher uniquement les câbles nécessaires, optimisant le flux d'air interne du boîtier.",
    "cool_air_tag": "Ventirad",
    "cool_air_desc": "Systèmes mécaniques ultra-fiables utilisant des ailettes métalliques et des ventilateurs pour une dissipation simple et durable.",
    "cool_liquid_tag": "Watercooling",
