    "ram_ddr5_desc": "Moderni standard za nove platforme. Veći protok i ugrađeni ECC. Kompleti obično počinju od 6000+ MT/s za optimalne performanse.",
    "ram_ddr4_tag": "Prethodna gen",
    "ram_ddr4_desc": "I dalje široko korišćena. Pristupačna, kompatibilna sa starijim i budžetskim konfiguracijama. Idealno: 16–32 GB na 3200–3600 MHz.",
    "ram_ddr3_tag": "Starija gen",
    "ram_ddr3_desc": "Nalazi se u starijim sistemima. Dobra za osnovnu kancelarijsku upotrebu, ali usko grlo za moderne zahtevne zadatke.",
    "ram_ddr2_tag": "Veoma staro",
    "ram_ddr2_desc": "Veoma ograničen protok i zastarela arhitektura — pogodno samo za očuvanje retro hardvera.",
    "storage_tag": "Skladištenje",
    "storage_title": "Tipovi Skladištenja",
    "storage_desc": "Gde se nalazi vaš operativni sistem određuje koliko će brz računar biti. Za većinu, NVMe SSD je pravi izbor.",
    "storage_nvme_tag": "Preporučeno",
    "storage_nvme_desc": "M.2 diskovi povezani preko PCIe magistrale. Moderne generacije postižu ekstremne brzine — trenutno podizanje sistema i aplikacija.",
    "storage_sata_tag": "Budžet",
    "storage_sata_desc": "2.5\" ili M.2 format, ograničen starijim SATA interfejsom. Ogroman korak napred u odnosu na bilo koji mehanički hard disk.",
    "storage_hdd_tag": "Masovno skladištenje",
    "storage_hdd_desc": "Mehanički čvrsti disk. Nepobediva cena po gigabajtu za velike fajlove i rezervne kopije — samo nemojte tu stavljati sistem.",
    "cpu_tag": "Procesor",
    "cpu_title": "Šta treba znati o procesorima",
    "cpu_desc": "Procesor je mozak računara. Izbor zavisi od rada: igre vole radni takt, kreativan rad voli veći broj jezgara.",
    "cpu_cores_tag": "Jezgra i niti",
    "cpu_cores_desc": "Više jezgara paralelno obavlja zadatke. Video renderovanje, inženjerske simulacije i strimovanje imaju najviše koristi.",
    "cpu_clock_tag": "Performanse",
    "cpu_clock_desc": "Meri se u GHz. Visok takt ubrzava pojedinačne zadatke. Kratke vršne frekvencije rešavaju se ugrađenim boost funkcijama.",
    "cpu_arch_tag": "Generacija",
    "cpu_arch_desc": "Rast IPC-a znači da će novije arhitekture na istom taktu pouzdano nadmašiti starije generacije čipova.",
    "cpu_tdp_tag": "Termika",
    "cpu_tdp_desc": "TDP pokazuje koliko toplote čip oslobađa. Visoka potrošnja zahteva efikasne i robusne rashladne sisteme.",
    "gpu_tag": "Grafika",
    "gpu_title": "Grafičke Karte",
    "gpu_desc": "GPU je najvažnija komponenta za igre i vizuelni rad. Renderuje svaki frejm koji vidite na ekranu.",
    "gpu_vram_tag": "VRAM",
    "gpu_vram_desc": "VRAM skladišti teksture. Moderne aplikacije i visoke rezolucije zahtevaju veće kapacitete, što osnovni nivo čini veoma važnim.",
    "gpu_upscale_tag": "Upscaling",
    "gpu_upscale_desc": "Inteligentni algoritmi omogućavaju hardveru da renderuje u nižoj rezoluciji i prikazuje sliku u višem dinamičkom kvalitetu.",
    "gpu_ray_tag": "Ray Tracing",
    "gpu_ray_desc": "Simulira fizičke putanje svetlosnih zraka. Predivni, ali veoma zahtevni proračuni koji traže namenska hardverska jezgra.",
    "gpu_pwr_tag": "Potrošnja",
    "gpu_pwr_desc": "Moćni grafički akceleratori povlače ogromnu struju. Planirajte kapacitet napajanja sa sigurnosnom marginom.",
    "psu_tag_top": "Infrastruktura",
    "psu_title": "Napajanje i Hlađenje",
    "psu_desc": "Temelj stabilnog sistema. Kvalitetna isporuka struje i pravilno odvođenje toplote garantuju dug vek hardvera.",
    "psu_efficiency_tag": "Efikasnost",
    "psu_efficiency_desc": "80 Plus sertifikati (Bronze, Gold, Platinum) predstavljaju efikasnost transformacije. Viši sertifikat znači manje otpadne toplote.",
    "psu_modularity_tag": "Modularnost",
    "psu_modularity_desc": "Potpuno modularne jedinice omogućavaju skidanje suvišnih kablova, čime se maksimizuje protok vazduha kroz kućište.",
    "cool_air_tag": "Vazdušno",
    "cool_air_desc": "Veoma pouzdani mehanički sistemi koji koriste metalna rebra i ventilatore za jednostavno i dugotrajno hlađenje.",
    "cool_liquid_tag": "Vodeno hlađenje",
    "cool_liquid_desc": "Tečne petlje koje odvode toplotu do velikih radijatora. Savršeno za kontrolu visokih radnih frekvencija procesora.",
