    "hero_link": "Chi siamo?",
    "formats_tag": "Fattore di forma",
    "formats_title": "Formati Scheda Madre",
    "formats_desc": "La scheda madre determina quali componenti sono compatibili. Le schede grandi offrono più slot; quelle piccole risparmiano spazio.",
    "formats_atx_tag": "Dimensioni intere",
    "formats_atx_desc": "Lo standard per la maggior parte dei PC fissi. Molti slot PCIe, slot RAM e ampio spazio per futuri upgrade.",
    "formats_matx_tag": "Dimensioni medie",
    "formats_matx_desc": "Una scelta equilibrata. Leggermente più piccola di ATX, supporta la maggior parte delle CPU a un prezzo inferiore.",
    "formats_itx_tag": "Compatta",
    "formats_itx_desc": "Dimensioni minime per case Small Form Factor. Limitata a uno slot PCIe e due banchi RAM — ma incredibilmente potente.",
    "formats_eatx_tag": "Entusiasta",
    "formats_eatx_desc": "Extended ATX per workstation e piattaforme HEDT. Massima espansione, supporto a doppia CPU su alcune schede.",
    "meta_size": "Dimensione",
    "meta_voltage": "Tensione",
    "meta_speed": "Velocità max",
    "ram_tag": "Memoria",
    "ram_title": "Generazioni di RAM",
    "ram_desc": "La velocità e la capacità della memoria di sistema influenzano il multitasking, i carichi di lavoro creativi e i fotogrammi nei giochi.",
    "ram_ddr5_tag": "Gen Attuale",
    "ram_ddr5_desc": "Lo standard moderno per le nuove piattaforme. Maggiore larghezza di banda e on-die ECC. I kit partono regolarmente da 6000+ MT/s per prestazioni ottimali.",
    "ram_ddr4_tag": "Gen Precedente",
    "ram_ddr4_desc": "Ancora ampiamente utilizzata. Economica, ampiamente compatibile con build datate o economiche. Il punto di equilibrio: 16–32 GB a 3200–3600 MHz.",
    "ram_ddr3_tag": "Legacy",
    "ram_ddr3_desc": "Presente nei sistemi datati. Ottima per l'uso base da ufficio, ma rappresenta un collo di bottiglia per i moderni carichi pesanti.",
    "ram_ddr2_tag": "Molto Vecchia",
    "ram_ddr2_desc": "Larghezza di banda fortemente limitata e architettura obsoleta — adatta solo per la conservazione di hardware storico.",
    "storage_tag": "Archiviazione",
    "storage_title": "Tipi di Archiviazione",
    "storage_desc": "L'unità in cui risiede l'OS definisce la reattività del PC. Per la maggior parte delle configurazioni, un SSD NVMe è la scelta ideale.",
    "storage_nvme_tag": "Consigliato",
    "storage_nvme_desc": "Unità M.2 collegate tramite PCIe. Le generazioni moderne raggiungono velocità eccezionali — avvio istantaneo di OS e app.",
    "storage_sata_tag": "Budget",
    "storage_sata_desc": "Fattore di forma da 2.5\" o M.2, limitato dalla vecchia interfaccia SATA. Un enorme passo avanti rispetto a qualsiasi hard disk meccanico.",
    "storage_hdd_tag": "Archiviazione di massa",
    "storage_hdd_desc": "Disco rigido meccanico. Prezzo per GB imbattibile per file di grandi dimensioni e backup — basta evitare di installarci l'OS.",
    "cpu_tag": "Processore",
    "cpu_title": "Cosa Sapere sulle CPU",
    "cpu_desc": "Il processore è il cervello della configurazione. La scelta dipende dal lavoro: i giochi amano la frequenza, i creativi il numero di core.",
    "cpu_cores_tag": "Conteggio Core",
    "cpu_cores_desc": "Più core gestiscono più compiti contemporaneamente. Rendering video, simulazioni ingegneristiche e streaming pesante ne beneficiano maggiormente.",
    "cpu_clock_tag": "Prestazioni",
    "cpu_clock_desc": "Misurata in GHz. Le frequenze alte accelerano i singoli task. I brevi picchi di carico sono gestiti dai sistemi di boost integrati.",
    "cpu_arch_tag": "Generazione",
    "cpu_arch_desc": "L'aumento dell'IPC significa che le nuove architetture a parità di clock supereranno in modo affidabile i vecchi modelli.",
    "cpu_tdp_tag": "Termiche",
    "cpu_tdp_desc": "Il TDP (Thermal Design Power) indica il calore generato. Potenze elevate richiedono sistemi di dissipazione robusti ed efficienti.",
    "gpu_tag": "Grafica",
    "gpu_title": "Carte Grafiche",
    "gpu_desc": "La GPU è il componente fondamentale per il gaming e i carichi visivi. Calcola ogni singolo fotogramma visualizzato a schermo.",
    "gpu_vram_tag": "VRAM",
    "gpu_vram_desc": "La VRAM memorizza le texture di gioco. Le applicazioni moderne e le alte risoluzioni scalano molto, rendendo le capacità di base fondamentali.",
    "gpu_upscale_tag": "Upscaling",
    "gpu_upscale_desc": "I motori di scaling intelligenti permettono all'hardware di elaborare le immagini a risoluzioni inferiori e mostrarle in qualità dinamica superiore.",
    "gpu_ray_tag": "Ray Tracing",
    "gpu_ray_desc": "Simula i percorsi fisici strutturali dei raggi di luce. Calcoli spettacolari ma esigenti che richiedono core dedicati.",
    "gpu_pwr_tag": "Consumo",
    "gpu_pwr_desc": "Gli acceleratori grafici potenti richiedono carichi energetici massicci. Pianifica l'alimentatore calcolando i giusti margini di sicurezza.",
    "psu_tag_top": "Infrastruttura",
    "psu_title": "Alimentazione e Dissipazione",
    "psu_desc": "La base di un sistema stabile. Un'erogazione di energia pulita e una corretta dissipazione del calore garantiscono la durata dei componenti.",
    "psu_efficiency_tag": "Efficienza",
    "psu_efficiency_desc": "Le certificazioni 80 Plus (Bronze, Gold, Platinum) indicano l'efficienza di conversione. Certificazioni alte significano meno calore disperso.",
    "psu_modularity_tag": "Modularità",
    "psu_modularity_desc": "Gli alimentatori completamente modulari permettono di rimuovere i cavi superflui, migliorando il flusso d'aria interno del case.",
    "cool_air_tag": "Ad Aria",
    "cool_air_desc": "Dissipatori meccanici ultra-affidabili che usano alette metalliche e ventole per un raffreddamento semplice e duraturo.",
    "cool_liquid_tag": "A Liquido",
    "cool_liquid_desc": "Sistemi a liquido che convogliano il calore verso grandi radiatori. Ideali per gestire le alte frequenze dei processori potenti.",
    "feat_1_title": "Ultimo Hardware",
    "feat_1_desc": "Guide aggiornate sui nuovi componenti non appena vengono lanciati.",
    "feat_2_title": "Guide Approfondite",
