    "hero_desc": "Todo lo que necesitas saber sobre hardware de PC: analizado, comparado y explicado para que montes tu equipo con total confianza.",
    "hero_link": "¿Quiénes somos?",
    "formats_tag": "Factor de forma",
    "formats_title": "Formatos de Placa Base",
    "formats_desc": "La placa base determina qué componentes caben en tu equipo. Las placas grandes ofrecen más expansión; las pequeñas ahorran espacio.",
    "formats_atx_tag": "Tamaño Completo",
    "formats_atx_desc": "El estándar para la mayoría de ordenadores de sobremesa. Muchos puertos PCIe, ranuras RAM y espacio para expandirse.",
    "formats_matx_tag": "Tamaño Medio",
    "formats_matx_desc": "Una opción equilibrada. Un poco más pequeña que la ATX, soporta la mayoría de procesadores a un precio menor.",
    "formats_itx_tag": "Compacta",
    "formats_itx_desc": "Tamaño mínimo para cajas Small Form Factor. Limitada a un puerto PCIe y dos ranuras RAM, pero sorprendentemente potente.",
    "formats_eatx_tag": "Entusiasta",
    "formats_eatx_desc": "ATX extendida para estaciones de trabajo. Máxima expansión, soporte para doble procesador en algunos modelos.",
    "meta_size": "Tamaño",
    "meta_voltage": "Voltaje",
    "meta_speed": "Velocidad máx",
    "ram_tag": "Memoria",
    "ram_title": "Generaciones de RAM",
    "ram_desc": "La velocidad y capacidad de la memoria del sistema afectan a la multitarea, al diseño creativo y a los FPS en juegos.",
    "ram_ddr5_tag": "Gen Actual",
    "ram_ddr5_desc": "El estándar moderno para nuevas plataformas. Mayor ancho de banda y ECC integrado. Los kits suelen partir de los 6000+ MT/s para un rendimiento óptimo.",
    "ram_ddr4_tag": "Gen Anterior",
    "ram_ddr4_desc": "Todavía muy utilizada. Económica, ampliamente compatible con configuraciones antiguas o de bajo presupuesto. El punto ideal: 16–32 GB a 3200–3600 MHz.",
    "ram_ddr3_tag": "Legado",
    "ram_ddr3_desc": "Presente en equipos antiguos. Sirve para tareas básicas de oficina, pero limita los procesos pesados modernos.",
    "ram_ddr2_tag": "Muy Antigua",
    "ram_ddr2_desc": "Ancho de banda severamente limitado y arquitectura obsoleta; ideal solo para preservar equipos antiguos clásicos.",
    "storage_tag": "Almacenamiento",
    "storage_title": "Tipos de Almacenamiento",
    "storage_desc": "El lugar donde instalas tu sistema operativo define la fluidez de tu PC. Para la mayoría, un SSD NVMe es la opción correcta.",
    "storage_nvme_tag": "Recomendado",
    "storage_nvme_desc": "Unidades M.2 conectadas por PCIe. Las generaciones modernas alcanzan velocidades increíbles, haciendo que la carga de apps sea instantánea.",
    "storage_sata_tag": "Presupuesto",
    "storage_sata_desc": "Factor de forma de 2.5\" o M.2, limitado por la interfaz clásica SATA. Una mejora masiva respecto a cualquier disco mecánico rígido.",
    "storage_hdd_tag": "Almacenamiento Masivo",
    "storage_hdd_desc": "Disco mecánico tradicional. Precio por GB insuperable para archivos pesados y copias de seguridad; evita instalar tu sistema operativo aquí.",
    "cpu_tag": "Procesador",
    "cpu_title": "Qué saber sobre las CPU",
    "cpu_desc": "El procesador es el cerebro de tu equipo. Elegir uno depende de tus tareas: los juegos prefieren velocidad de reloj; el trabajo creativo, más núcleos.",
    "cpu_cores_tag": "Núcleos e Hilos",
    "cpu_cores_desc": "Más núcleos procesan más tareas simultáneamente. La edición de vídeo, simulaciones complejas y directos se benefician enormemente.",
    "cpu_clock_tag": "Rendimiento",
    "cpu_clock_desc": "Medido en GHz. Las frecuencias altas aceleran las tareas monohilo. Las frecuencias pico cortas las gestiona el modo boost automático.",
    "cpu_arch_tag": "Generación",
    "cpu_arch_desc": "El incremento del IPC significa que las arquitecturas nuevas a la misma velocidad superarán con creces a las versiones anteriores.",
    "cpu_tdp_tag": "Térmicos",
    "cpu_tdp_desc": "El TDP (Thermal Design Power) guía la elección de la refrigeración. Potencias altas requieren bloques de disipación eficientes y robustos.",
    "gpu_tag": "Gráficos",
    "gpu_title": "Tarjetas Gráficas",
    "gpu_desc": "La GPU es el componente más importante para jugar y realizar trabajos visuales. Renderiza cada fotograma que ves en pantalla.",
    "gpu_vram_tag": "VRAM",
    "gpu_vram_desc": "La VRAM almacena las texturas. Las aplicaciones y resoluciones actuales demandan mucha capacidad, haciendo que la memoria base sea muy importante.",
    "gpu_upscale_tag": "Reescalado",
    "gpu_upscale_desc": "Los motores de reescalado inteligente permiten procesar imágenes a resoluciones menores y mostrarlas en calidades dinámicas superiores.",
    "gpu_ray_tag": "Ray Tracing",
    "gpu_ray_desc": "Simula las trayectorias físicas de los rayos de luz. Cálculos espectaculares pero exigentes que requieren núcleos acelerados por hardware.",
    "gpu_pwr_tag": "Consumo",
    "gpu_pwr_desc": "Las tarjetas gráficas potentes exigen mucha energía. Planifica tu fuente de alimentación calculando buenos márgenes de seguridad.",
    "psu_tag_top": "Infraestructura",
    "psu_title": "Energía y Refrigeración",
    "psu_desc": "La base de un sistema estable. Un suministro de energía limpio y una disipación de calor correcta aseguran la longevidad del hardware.",
    "psu_efficiency_tag": "Eficiencia",
    "psu_efficiency_desc": "Las certificaciones 80 Plus (Bronze, Gold, Platinum) indican la eficiencia de conversión. Una certificación alta significa menos calor residual generado.",
    "psu_modularity_tag": "Modularidad",
    "psu_modularity_desc": "Las fuentes modulares permiten quitar los cables sobrantes, maximizando el flujo de aire interno de la caja.",
    "cool_air_tag": "Por Aire",
    "cool_air_desc": "Disipadores mecánicos muy fiables que usan aletas metálicas y ventiladores para un enfriamiento simple y de larga duración.",
    "cool_liquid_tag": "Líquida",
    "cool_liquid_desc": "Circuitos cerrados que envían el calor a grandes radiadores. Perfecto para controlar altas frecuencias en procesadores potentes.",
