    "nav_psu_cooling": "Fontes e Refrigeração",
    "nav_about": "Sobre nós",
    "nav_build_btn": "Monte seu PC",
    "hero_sub": "Inteligência de Hardware",
    "hero_tagline": "Construa melhor. Seja melhor.",
    "hero_desc": "Tudo o que você precisa saber sobre hardware de PC — explorado, comparado e explicado para você montar com total confiança.",
    "hero_link": "Quem somos nós?",
    "formats_tag": "Fator de forma",
    "formats_title": "Formatos de Placa-Mãe",
    "formats_desc": "A placa-mãe determina quais componentes cabem no seu computador. Placas maiores oferecem mais expansão; as menores economizam espaço.",
    "formats_atx_tag": "Tamanho Total",
    "formats_atx_desc": "O padrão para a maioria dos computadores de mesa. Muitas portas PCIe, slots de RAM e espaço para upgrade.",
    "formats_matx_tag": "Tamanho Médio",
    "formats_matx_desc": "Uma escolha equilibrada. Um pouco menor que a ATX, suporta a maioria dos processadores por um preço menor.",
    "formats_itx_tag": "Compacta",
    "formats_itx_desc": "Tamanho mínimo para gabinetes Small Form Factor. Limitada a um slot PCIe e dois slots de RAM — mas surpreendentemente potente.",
    "formats_eatx_tag": "Entusiasta",
    "formats_eatx_desc": "ATX estendida para estações de trabalho. Máxima expansão, suporte a dois processadores em alguns modelos.",
    "meta_size": "Tamanho",
    "meta_voltage": "Voltagem",
    "meta_speed": "Velocidade máx",
    "ram_tag": "Memória",
    "ram_title": "Gerações de RAM",
    "ram_desc": "A velocidade e capacidade da memória do sistema afetam o multitasking, trabalhos criativos e as taxas de quadros em jogos.",
    "ram_ddr5_tag": "Geração Atual",
    "ram_ddr5_desc": "O padrão moderno para novas plataformas. Maior largura de banda e ECC integrado. Os kits começam em 6000+ MT/s para desempenho ideal.",
    "ram_ddr4_tag": "Geração Anterior",
    "ram_ddr4_desc": "Ainda muito utilizada. Barata, amplamente compatível com configurações antigas ou econômicas. O ponto ideal: 16–32 GB a 3200–3600 MHz.",
    "ram_ddr3_tag": "Legado",
    "ram_ddr3_desc": "Encontrada em sistemas antigos. Boa para uso básico de escritório, mas limita processos pesados modernos.",
    "ram_ddr2_tag": "Muito Antiga",
    "ram_ddr2_desc": "Largura de banda severamente limitada e arquitetura obsoleta — ideal apenas para preservar hardware antigo clássico.",
    "storage_tag": "Armazenamento",
    "storage_title": "Tipos de Armazenamento",
    "storage_desc": "Onde o seu sistema operacional fica define a fluidez do seu PC. Para a maioria, um SSD NVMe é a escolha certa.",
    "storage_nvme_tag": "Recomendado",
    "storage_nvme_desc": "Unidades M.2 conectadas por PCIe. As gerações modernas alcançam velocidades incríveis — carregamento instantâneo do sistema e apps.",
    "storage_sata_tag": "Econômico",
    "storage_sata_desc": "Fator de forma de 2.5\" ou M.2, limitado pela interface SATA antiga. Uma evolução massiva em comparação a qualquer disco rígido mecânico.",
    "storage_hdd_tag": "Armazenamento em Massa",
    "storage_hdd_desc": "Disco mecânico tradicional. Preço por GB imbatível para arquivos grandes e backups — apenas evite instalar o sistema operacional aqui.",
    "cpu_tag": "Processador",
    "cpu_title": "O que Saber sobre as CPUs",
    "cpu_desc": "O processador é o cérebro do seu computador. A escolha depende das suas tarefas: jogos preferem velocidade de clock; trabalho criativo prefere mais núcleos.",
    "cpu_cores_tag": "Núcleos e Threads",
    "cpu_cores_desc": "Mais núcleos processam mais tarefas simultaneamente. Edição de vídeo, simulações complexas e transmissões ao vivo ganham muito.",
    "cpu_clock_tag": "Desempenho",
    "cpu_clock_desc": "Medido em GHz. Frequências altas aceleram tarefas de thread única. Frequências de pico curtas são gerenciadas pelo modo boost automático.",
    "cpu_arch_tag": "Geração",
    "cpu_arch_desc": "O aumento do IPC significa que arquiteturas novas à mesma velocidade superarão com facilidade as versões antigas.",
    "cpu_tdp_tag": "Térmicos",
    "cpu_tdp_desc": "O TDP (Thermal Design Power) guia a escolha da refrigeração. Potências altas exigem blocos de dissipação eficientes e robustos.",
    "gpu_tag": "Gráficos",
    "gpu_title": "Placas de Vídeo",
    "gpu_desc": "A GPU é o componente mais importante para jogos e trabalhos visuais. Renderiza cada quadro que você vê na tela.",
    "gpu_vram_tag": "VRAM",
    "gpu_vram_desc": "A VRAM armazena texturas. Aplicativos e resoluções modernas demandam muita capacidade, tornando a memória base extremamente importante.",
    "gpu_upscale_tag": "Upscaling",
    "gpu_upscale_desc": "Motores de reescalonamento inteligente permitem processar imagens em resoluções menores e exibi-las em qualidades dinâmicas superiores.",
    "gpu_ray_tag": "Ray Tracing",
    "gpu_ray_desc": "Simula as trajetórias físicas dos raios de luz. Cálculos espetaculares, mas exigentes, que requerem núcleos acelerados por hardware.",
    "gpu_pwr_tag": "Consumo",
    "gpu_pwr_desc": "Placas de vídeo potentes exigem muita energia. Planeje sua fonte de alimentação calculando boas margens de segurança.",
    "psu_tag_top": "Infraestrutura",
    "psu_title": "Energia e Refrigeração",
    "psu_desc": "A base de um sistema estável. Fornecimento de energia limpo e dissipação de calor correta garantem a longevidade do hardware.",
    "psu_efficiency_tag": "Eficiência",
    "psu_efficiency_desc": "As certificações 80 Plus (Bronze, Gold, Platinum) indicam a eficiência de conversão. Certificação alta significa menos calor residual gerado.",
    "psu_modularity_tag": "Modularidade",
    "psu_modularity_desc": "Fontes modulares permitem remover os cabos excedentes, maximizando o fluxo de ar interno do gabinete.",
    "cool_air_tag": "Por Aire",
    "cool_air_desc": "Dissipadores mecânicos muito confiáveis que usam aletas metálicas e ventoinhas para um resfriamento simples e de longa duração.",
    "cool_liquid_tag": "Líquida",
    "cool_liquid_desc": "Circuitos fechados que enviam o calor para grandes radiadores. Perfeito para controlar altas frequências em processadores potentes.",
    "feat_1_title": "Último Hardware",
    "feat_1_desc": "Guias atualizados sobre os novos lançamentos do mercado.",
