    "ram_ddr5_tag": "Nuvarande gen",
    "ram_ddr5_desc": "Den moderna standarden för nya plattformar. Högre bandbredd och inbyggd ECC. Minneskit presterar bäst vid 6000+ MT/s.",
    "ram_ddr4_tag": "Föregående gen",
    "ram_ddr4_desc": "Fortfarande väldigt utbrett. Prisvärt, brett kompatibelt med äldre eller budgetkonfigurationer. Optimalt val: 16–32 GB vid 3200–3600 MHz.",
    "ram_ddr3_tag": "Äldre gen",
    "ram_ddr3_desc": "Hittas i gamla system. Fungerar för enklare kontorsarbete, men är en flaskhals för moderna tunga applikationer.",
    "ram_ddr2_tag": "Mycket gammalt",
    "ram_ddr2_desc": "Allvarligt begränsad bandbredd och föråldrad arkitektur — endast lämpligt för att bevara retro-hårdvara.",
    "storage_tag": "Lagring",
    "storage_title": "Lagringstyper",
    "storage_desc": "Var ditt operativsystem är installerat avgör hur snabb datorn känns. En NVMe SSD är det rätta valet för de flesta builds.",
    "storage_nvme_tag": "Rekommenderas",
    "storage_nvme_desc": "PCIe-anslutna M.2-enheter. Moderna generationer når extrema hastigheter — i princip omedelbar laddning av OS och appar.",
    "storage_sata_tag": "Budget",
    "storage_sata_desc": "2.5\"- eller M.2-format, begränsat av det äldre SATA-gränssnittet. En enorm uppgradering jämfört med en mekanisk hårddisk.",
    "storage_hdd_tag": "Masslagring",
    "storage_hdd_desc": "Mekanisk rotationsdisk. Ofslagbart pris per GB för stora filer och säkerhetskopior — men undvik att installera ditt OS här.",
    "cpu_tag": "Processor",
    "cpu_title": "Värt att veta om processorer",
