    "cpu_cores_tag": "Kärnor & Trådar",
    "cpu_cores_desc": "Fler kärnor hanterar fler uppgifter samtidigt. Videorendering, tunga simuleringar och streaming drar störst nytta.",
    "cpu_clock_tag": "Prestanda",
    "cpu_clock_desc": "Mäts i GHz. Hög klockfrekvens snabbar upp enkeltrådade uppgifter. Korta belastningstoppar hanteras av inbyggda boost-lägen.",
    "cpu_arch_tag": "Generation",
    "cpu_arch_desc": "Högre IPC innebär att nyare arkitekturer vid samma klockfrekvens pålitligt kör ifrån äldre modeller.",
    "cpu_tdp_tag": "Termik",
    "cpu_tdp_desc": "TDP (Thermal Design Power) anger hur mycket värme chippet avger. Hög effekt kräver effektiva och robusta kylningslösningar.",
    "gpu_tag": "Grafik",
    "gpu_title": "Grafikkort",
    "gpu_desc": "Grafikkortet är den viktigaste komponenten för spel och visuellt arbete. Det renderar varje bildruta du ser på skärmen.",
    "gpu_vram_tag": "VRAM",
    "gpu_vram_desc": "VRAM lagrar texturer. Moderna applikationer och höga upplösningar kräver mycket minne, vilket gör baskapaciteten mycket viktig.",
    "gpu_upscale_tag": "Uppskalning",
    "gpu_upscale_desc": "Intelligenta skalningsmotorer gör att grafikkortet kan rendera i lägre upplösning och visa bilden i högre dynamisk kvalitet.",
    "gpu_ray_tag": "Raytracing",
    "gpu_ray_desc": "Simulerar ljusstrålars fysiska väg. Vackra men krävande beräkningar som kräver hårdvaruaccelererade kärnor.",
    "gpu_pwr_tag": "Strömförbrukning",
    "gpu_pwr_desc": "Kraftfulla grafikkort drar enormt mycket ström. Planera ditt nätaggregat med goda säkerhetsmarginaler.",
