    "storage_desc": "Къде се намира операционната ви система определя бързината на компютъра. За повечето системи NVMe SSD е правилният избор.",
    "storage_nvme_tag": "Препоръчително",
    "storage_nvme_desc": "M.2 дискове, свързани чрез PCIe. Модерните поколения достигат екстремни скорости — мигновено зареждане на ОС и приложения.",
    "storage_sata_tag": "Бюджетен",
    "storage_sata_desc": "2.5\" или M.2 формат, ограничен от по-стария SATA интерфейс. Огромно подобрение спрямо всеки механичен твърд диск.",
    "storage_hdd_tag": "Масово съхранение",
    "storage_hdd_desc": "Механичен твърд диск. Ненадмината цена за гигабайт за големи файлове и резервни копия — просто не инсталирайте ОС тук.",
    "cpu_tag": "Процесор",
    "cpu_title": "Какво трябва да знаете за CPU",
    "cpu_desc": "Процесорът е мозъкът на компютъра. Изборът зависи от нуждите: игрите предпочитат тактова честота, работата — брой ядра.",
    "cpu_cores_tag": "Ядра и нишки",
    "cpu_cores_desc": "Повече ядра обработват повече задачи едновременно. Видео обработката, симулациите и стриймингът печелят най-много.",
    "cpu_clock_tag": "Производителност",
    "cpu_clock_desc": "Измерва се в GHz. Високите честоти ускоряват еднонишковите задачи. Кратките пикови натоварвания се поемат от вградения буст.",
    "cpu_arch_tag": "Поколение",
    "cpu_arch_desc": "Увеличението на IPC означава, че по-новите архитектури при еднаква честота ще изпреварят по-старите версии.",
    "cpu_tdp_tag": "Термични",
    "cpu_tdp_desc": "TDP показва колко топлина отделя чипът. Високата консумация изисква ефективни и мощни охладителни системи.",
    "gpu_tag": "Графика",
    "gpu_title": "Видеокарти",
    "gpu_desc": "GPU е най-важният компонент за игри и визуална работа. Рендерира всеки кадър, който виждате на екрана.",
    "gpu_vram_tag": "VRAM",
    "gpu_vram_desc": "VRAM съхранява текстурите. Съвременните приложения и високи резолюции изискват голям капацитет, което прави базата изключително важна.",
    "gpu_upscale_tag": "Ъпскейлинг",
    "gpu_upscale_desc": "Интелигентните алгоритми позволяват на хардуера да рендерира в по-ниска резолюция и да показва картина с по-високо качество.",
    "gpu_ray_tag": "Рей трейсинг",
    "gpu_ray_desc": "Симулира физическия път на светлинните лъчи. Красиви, но изключително тежки изчисления, изискващи хардуерни RT ядра.",
    "gpu_pwr_tag": "Консумация",
    "gpu_pwr_desc": "Мощните видеокарти консумират огромно количество енергия. Планирайте захранването с добри маржове за безопасност.",
    "psu_tag_top": "Инфраструктура",
    "psu_title": "Захранване и охлаждане",
    "psu_desc": "Фундаментът на стабилната система. Качественото захранване и правилното отвеждане на топлина гарантират дълъг живот на хардуера.",
    "psu_efficiency_tag": "Ефективност",
    "psu_efficiency_desc": "Сертификатите 80 Plus (Bronze, Gold, Platinum) отразяват КПД на захранването. Високият сертификат означава по-малко отделена топлина.",
    "psu_modularity_tag": "Модулност",
    "psu_modularity_desc": "Напълно модулните захранвания позволяват премахване на излишните кабели, подобрявайки въздушния поток в кутията.",
    "cool_air_tag": "Въздушно",
    "cool_air_desc": "Надеждни въздушни охладители с метални ребра и вентилатори. Проста и изключително дълготрайна конструкция.",
    "cool_liquid_tag": "Водно",
    "cool_liquid_desc": "Течни системи, отвеждащи топлината към големи радиатори. Перфектни за овладяване на температурните скокове при мощни процесори.",
    "feat_1_title": "Най-новият хардуер",
    "feat_1_desc": "Актуализирани ръководства за нови компоненти веднага след излизането им.",
    "feat_2_title": "Подробни гайдове",
    "feat_2_desc": "Разберете какво купувате, преди да похарчите парите си.",
    "feat_3_title": "Сравни и реши",
    "feat_3_desc": "Реални спецификации, истински тестове, без излишен маркетинг.",
    "feat_4_title": "Сглобявай смело",
    "feat_4_desc": "Проверка за съвместимост и списъци с части за всеки бюджет.",
    "footer_build": "Сглобявай умно.",
    "nav_back": "← Назад към ръководството",
