    "page_title": "Сглобете вашия компютър",
    "page_desc": "Изберете вашите компоненти по-долу. Цените се обновяват в реално време и включват гръцко ДДС (24%). Превключвайте между модерни и стари платформи за конфигурация и на по-стари машини.",
    "btn_modern": "🟧 Модерна (DDR4 / DDR5)",
