    "nav_psu_cooling": "Furnizimi & Ftohja",
    "nav_about": "Rreth nesh",
    "nav_build_btn": "Ndërto PC-në tënde",
    "hero_sub": "Inteligjenca e Harduerit",
    "hero_tagline": "Ndërto më mirë. Bëhu më i mirë.",
    "hero_desc": "Gjithçka që duhet të dish për harduerin e PC-së — eksploruar, krahasuar dhe shpjeguar që të ndërtosh me besim.",
    "hero_link": "Kush jemi ne?",
    "formats_tag": "Formati",
    "formats_title": "Formatet e Motherboard-it",
    "formats_desc": "Motherboard-i përcakton se cilat komponentë përshtaten në ndërtimin tënd. Bordet më të mëdha ofrojnë më shumë slote zgjerimi; ato më të vogla kursejnë hapësirë.",
    "formats_atx_tag": "Madhësi e Plotë",
    "formats_atx_desc": "Standardi për shumicën e ndërtimeve desktop. Shumë slote PCIe, slote RAM, dhe hapësirë për t'u rritur.",
    "formats_matx_tag": "Madhësi Mesatare",
    "formats_matx_desc": "Një zgjedhje e balancuar. Pak më e vogël se ATX, mbështet ende shumicën e CPU-ve dhe kartave të zgjerimit me çmim më të ulët.",
    "formats_itx_tag": "Kompakt",
    "formats_itx_desc": "Gjurmë e vogël për kasat me formë të vogël. Kufizuar në një slot PCIe dhe dy shkopinj RAM — por mbresëlënëse e aftë.",
    "formats_eatx_tag": "Entuziast",
    "formats_eatx_desc": "ATX i zgjeruar për stacione pune dhe platforma HEDT. Zgjerim maksimal, mbështetje për dy CPU në disa borde.",
    "meta_size": "Madhësia",
    "meta_voltage": "Voltazhi",
    "meta_speed": "Shpejtësia maksimale",
    "ram_tag": "Memorja",
    "ram_title": "Gjeneratat e RAM-it",
    "ram_desc": "Shpejtësia dhe kapaciteti i memories së sistemit ndikojnë në shumëdetyrim, ngarkesat krijuese dhe kuadrot e lojërave.",
    "ram_ddr5_tag": "Gjenerata Aktuale",
    "ram_ddr5_desc": "Standardi modern për platformat moderne. Bandwidth më i lartë dhe ECC në chip. Kitet zakonisht fillojnë nga 6000+ MT/s për pika optimale përpunimi.",
    "ram_ddr4_tag": "Gjenerata e Kaluar",
    "ram_ddr4_desc": "Ende e përdorur gjerësisht. E përballueshme, e përputhshme gjerësisht me konfigurime të vjetra dhe me buxhet të kufizuar. Pika ideale: 16–32 GB në 3200–3600 MHz.",
    "ram_ddr3_tag": "E Vjetruar",
    "ram_ddr3_desc": "Gjendet në ndërtime të vjetra. Mirë për përdorim bazë zyre, por një pengesë për kërkesat moderne të përpunimit të rëndë.",
    "ram_ddr2_tag": "Shumë e Vjetër",
    "ram_ddr2_desc": "Bandwidth dhe arkitekturë standarde shumë të kufizuara — e përshtatshme vetëm për ruajtjen e harduerit klasik të vjetër.",
    "storage_tag": "Ruajtja",
    "storage_title": "Llojet e Ruajtjes",
    "storage_desc": "Ku jeton sistemi yt operativ përcakton sa shpejt ndihet PC-ja jote. Për shumicën e ndërtimeve, një SSD NVMe për diskun e OS-it është zgjedhja e duhur.",
    "storage_nvme_tag": "E Rekomanduar",
    "storage_nvme_desc": "Disqe M.2 të lidhur me PCIe. Gjeneratat moderne arrijnë shpejtësi të jashtëzakonshme—praktikisht të menjëhershme për OS dhe ngarkim aplikacionesh.",
    "storage_sata_tag": "Ekonomike",
    "storage_sata_desc": "Formë 2.5\" ose M.2, e kufizuar nga ndërfaqja e vjetër SATA. Përmirësim i madh krahasuar me çdo disk mekanik rrotullues.",
    "storage_hdd_tag": "Ruajtje Masive",
    "storage_hdd_desc": "Disk mekanik rrotullues. Kosto për GB e paarritshme për skedarë të mëdhenj, grupe disqesh dhe backup — thjesht shmang vendosjen e OS-it kryesor këtu.",
    "cpu_tag": "Procesori",
    "cpu_title": "Çfarë Duhet të Dini për CPU-të",
    "cpu_desc": "Procesori është truri i ndërtimit tënd. Zgjedhja e njërit varet nga ngarkesa jote e punës: lojërat favorizojnë shpejtësinë e clock-ut, puna krijuese favorizon numrin e bërthamave.",
    "cpu_cores_tag": "Numri i Bërthamave",
    "cpu_cores_desc": "Më shumë bërthama trajtojnë më shumë detyra pa probleme. Renderimi i videove, simulimet inxhinierike dhe setup-et e rënda të streaming-ut përfitojnë më së shumti.",
    "cpu_clock_tag": "Performanca",
    "cpu_clock_desc": "Matur në GHz. Clock-et e larta maksimizojnë detyrat me një fill. Frekuencat e larta operacionale afatshkurtra trajtohen nga hapat e boost-it të integruar.",
    "cpu_arch_tag": "Gjenerata",
    "cpu_arch_desc": "Rritjet e IPC nënkuptojnë se arkitekturat e reja në të njëjtat shpejtësi clock do të kalojnë me besueshmëri iteracionet e vjetra.",
    "cpu_tdp_tag": "Termika",
    "cpu_tdp_desc": "Fuqia Termike e Projektimit udhëzon zgjedhjen tënde të zgjidhjeve termike. Prodhimet e larta të fuqisë kërkojnë blloqe ftohjeje efikase dhe të fuqishme.",
    "gpu_tag": "Grafika",
    "gpu_title": "Kartat Grafike",
    "gpu_desc": "GPU-ja është komponenti më i rëndësishëm për lojëra dhe ngarkesa vizuale. Ajo rendon çdo kuadro që sheh në ekran.",
    "gpu_vram_tag": "VRAM",
    "gpu_vram_desc": "VRAM-i mban teksturat e përpunimit. Aplikacionet dhe rezolucionet moderne shkallëzohen agresivisht, duke bërë kapacitetet bazë shumë të rëndësishme.",
    "gpu_upscale_tag": "Upscaling",
    "gpu_upscale_desc": "Motorët inteligjentë të shkallëzimit lejojnë harduerin grafik të llogarisë konfigurime në dimensione më të ulëta dhe të shfaqë objektiva dinamikë më të lartë.",
    "gpu_ray_tag": "Ray Tracing",
    "gpu_ray_desc": "Simulon rrugët fizike strukturore të rrezeve të dritës. Llogaritje bukur kërkuese që kërkojnë bërthama të përshpejtuara nga harduer.",
    "gpu_pwr_tag": "Konsumi i Energjisë",
    "gpu_pwr_desc": "Përshpejtuesit e rëndë grafikë tërheqin ngarkesa masive operacionale. Përputh me kujdes kapacitetet e linjës me marzhe sigurie.",
    "psu_tag_top": "Infrastruktura",
    "psu_title": "Fuqia & Ftohja",
    "psu_desc": "Themeli i një sistemi të qëndrueshëm. Furnizimi i pastër me cilësi dhe shpërndarja e duhur e nxehtësisë sigurojnë cikle jete të gjata të harduerit.",
    "psu_efficiency_tag": "Efikasiteti",
    "psu_efficiency_desc": "Certifikimet 80 Plus përfaqësojnë efikasitetin e pastër të transformimit. Certifikimi më i lartë përkthehet në më pak nxehtësi të humbur.",
    "psu_modularity_tag": "Modulariteti",
    "psu_modularity_desc": "Njësitë plotësisht modulare mbështesin konfigurime të shkëputshme, duke maksimizuar hapësirën e rrjedhës së ajrit brenda shasive moderne.",
    "cool_air_tag": "Ftohje me Ajër",
    "cool_air_desc": "Setup-e strukturore mekanike shumë të besueshme që përdorin sisteme gjethesh metalike dhe operim të vazhdueshëm ventilatorësh për ekzekutim afatgjatë të thjeshtë.",
    "cool_liquid_tag": "Ftohje me Lëng",
    "cool_liquid_desc": "Qarqe lëngu që drejtojnë nxehtësinë drejt matricave të mëdha radiatorësh. Perfekte për menaxhimin e frekuencave agresive të përpunimit dhe pikëve maksimale në mënyrë të qetë.",
    "feat_1_title": "Harduerimi më i Ri",
    "feat_1_desc": "Udhëzues të përditësuar për lançimet e reja ndërsa dalin.",
    "feat_2_title": "Udhëzues të Thelluar",
    "feat_2_desc": "Kupto çfarë po blen para se të shpenzosh.",
    "feat_3_title": "Krahaso & Vendos",
    "feat_3_desc": "Specifikime reale, benchmarks reale, pa fjalë të tepërta.",
    "feat_4_title": "Ndërto me Besim",
    "feat_4_desc": "Kontrolle përputhshmërie dhe lista pjesësh për çdo buxhet.",
    "footer_build": "Ndërto mençur.",
