    "page_title": "Ndërto PC-në tënde",
    "page_desc": "Zgjidh komponentët e tu më poshtë. Çmimet përditësohen në kohë reale dhe përfshijnë TVSH-në greke (24%). Kalo midis platformave Moderne dhe të Vjetra për të konfiguruar edhe makina më të vjetra.",
    "btn_modern": "🟧 Modern (DDR4 / DDR5)",
