    "legacy_note": "⚠️ Pjesë të rikonstruktuara / të përdorura. Çmimet e treguara janë vlerësime të përafërta për tregun e dorës së dytë (tregu grek). Këto platforma nuk prodhohen më si të reja — pjesët merren nga makina më të vjetra. Çmimet me ngjyrë vjollcë tregojnë pjesë të përdorura/të rikonstruktuara.",
