    "about_hero_eyebrow": "Хто ми",
    "about_hero_title": "Одна людина.<br><em>Багато</em> ПК.",
    "about_hero_desc": "betterPC — це проєкт однієї людини, що народився з простого розчарування: <strong>занадто багато людей переплачують за комп'ютери, яких вони не розуміють</strong>, або викидають цілком робоче старе залізо лише тому, що ніхто не сказав їм, що воно ще може добре працювати.<br><br>Збираєте новий ігровий комп'ютер чи рятуєте DDR2-машину для бабусі — цей сайт вам допоможе.",
    "about_avatar_name": "Засновник",
    "about_avatar_role": "Засновник · <span style='color: white;'>better</span><span style='color: #ff7a00;'>PC</span>",
    "about_avatar_bio": "Ентузіаст ПК, любитель поколупатись у залізі та переробник старого обладнання. Я збирав усе — від бюджетних офісних коробок з DDR2 до ігрових монстрів на водяному охолодженні — і вважаю, що кожен заслуговує знати, що всередині його машини.",
