    "about_v1_title": "Чесні ціни",
    "about_v1_desc": "Ціни є орієнтовними і позначені як такі. Жодних завищених цифр, щоб інші збірки здавались дешевшими.",
    "about_v2_title": "Без реклами, без партнерок",
    "about_v2_desc": "betterPC нічого не заробляє на рекомендації конкретних брендів. Вибір базується на цінності та наявності.",
    "about_v3_title": "Старе залізо теж має значення",
    "about_v3_desc": "Машини на DDR2 та DDR3 усе ще можуть служити реальним цілям. Допомогти видобути з них ще трохи життя — варте справи.",
