    "about_v4_desc": "Нічого не рекомендується без перевірки. Сумісність процесора, материнської плати й пам'яті перевіряється до того, як ви витратите гроші.",
    "about_v5_title": "Грецький контекст",
    "about_v5_desc": "Ціни, наявність і поради щодо комплектуючих орієнтовані на грецький та ширший ринок ЄС, а не на американський.",
    "about_v6_title": "Постійне вдосконалення",
    "about_v6_desc": "Списки комплектуючих, ціни та посібники оновлюються разом зі змінами ринку. Це не сайт «зробив і забув».",
