    "services_s3_title": "Апгрейд заліза",
    "services_s3_desc": "Оперативна пам'ять, SSD, відеокарта — що б не потребував ваш ПК.",
    "services_s4_title": "Повільний комп'ютер?",
    "services_s4_desc": "Діагностика та прискорення продуктивності.",
    "services_s5_title": "Збірка ПК",
    "services_s5_desc": "Допомога з вибором комплектуючих та повна збірка з нуля.",
    "services_price_note": "💬 Ціна залежить від складності роботи — напишіть мені для оцінки, перш ніж ми щось почнемо.",
    "services_area": "📍 Обслуговую Хайдарі та ширшу Афінську агломерацію. Виїзд додому або принесіть ПК самі — як вам зручніше.",
