    "page_desc": "Ընտրեք ձեր բաղադրիչները ստորև։ Գները թարմացվում են իրական ժամանակում և ներառում են հունական ԱԱՀ (24%)։ Անցեք ժամանակակից և հին հարթակների միջև՝ հին մեքենաներ կազմաձևելու համար։",
