    "w_intel_mismatch": "⚠️ Պրոցեսոր–մայր տախտակ անհամապատասխանություն. Intel պրոցեսորը պահանջում է LGA1700 (B660/B760/Z790)։",
    "w_amd_mismatch": "⚠️ Պրոցեսոր–մայր տախտակ անհամապատասխանություն. AMD պրոցեսորը պահանջում է AM4 կամ AM5 տախտակ։",
