    "about_v2_title": "Առանց գովազդի, առանց ընկերակցային կապերի",
    "about_v2_desc": "betterPC-ն ոչինչ չի վաստակում կոնկրետ բրենդներ առաջարկելուց։ Ընտրությունները հիմնված են արժեքի և հասանելիության վրա։",
