    "services_price_note": "💬 Գները կախված են աշխատանքից — գրեք ինձ գնահատականի համար, նախքան որևէ բան սկսելը։",
    "services_area": "📍 Սպասարկում եմ Խայդարին և ընդհանուր Աթենքի ավազանը։ Այցելություն տուն կամ բերեք ձեր համակարգիչը — ինչպես ձեզ հարմար է։",
    "services_about_title": "Ով եմ ես",
    "services_about_desc": "Ես աշխատում եմ PC սարքաշարի հետ, հավաքում եմ համակարգեր և սիրում եմ օգնել մարդկանց լուծել իրենց խնդիրները՝ առանց խանութում մի ամբողջ ունեցվածք վճարելու։ Եթե ինչ-որ բան ճիշտ չի աշխատում, եկեք միասին պարզենք։"
