    "about_hero_eyebrow": "ვინ ვართ ჩვენ",
    "about_hero_title": "ერთი ადამიანი.<br><em>ბევრი</em> კომპიუტერი.",
    "about_hero_desc": "betterPC არის ერთი ადამიანის პროექტი, რომელიც წარმოიშვა უბრალო იმედგაცრუებისგან: <strong>ძალიან ბევრი ადამიანი ზედმეტს იხდის ისეთ კომპიუტერებში, რომლებსაც არ ესმის</strong>, ან აგდებს სავსებით გამართულ ძველ ტექნიკას მხოლოდ იმიტომ, რომ არავინ უთხრა, რომ ის კვლავ კარგად იმუშავებდა.<br><br>ახალ სათამაშო კომპიუტერს აწყობთ თუ ბებია-ბაბუისთვის DDR2 მანქანას გადაარჩენთ, ეს საიტი დაგეხმარებათ.",
    "about_avatar_name": "დამფუძნებელი",
    "about_avatar_role": "დამფუძნებელი · <span style='color: white;'>better</span><span style='color: #ff7a00;'>PC</span>",
    "about_avatar_bio": "კომპიუტერების მოყვარული, ექსპერიმენტატორი და ძველი ტექნიკის გადამამუშავებელი. ავაწყე ყველაფერი — DDR2-ით აღჭურვილი ბიუჯეტური საოფისე კომპიუტერებიდან წყლის გაგრილებით სათამაშო მანქანებამდე — და მჯერა, რომ ყველას აქვს უფლება იცოდეს, რა არის მისი მანქანის შიგნით.",
    "about_story_eyebrow": "ისტორია",
    "about_story_title": "რატომ არსებობს better<span style='color: #ff7a00;'>PC</span>",
    "about_story_h1": "ძველი ტექნიკის პრობლემა",
    "about_story_p1": "საბერძნეთში მილიონობით 2006–2015 წლების კომპიუტერი უბრალოდ საწყობებში ინახება...",
    "about_story_h2": "აწყობის კონფიგურატორი",
    "about_story_p2": "არცერთი სხვა ბერძნული PC გზამკვლევი არ მოიცავს DDR2 და DDR3 პლატფორმებს...",
    "about_story_h3": "შექმნილია საბერძნეთის ბაზრისთვის",
    "about_story_p3": "ფასები მოიცავს 24%-იან ბერძნულ დღგ-ს და ასახავს იმას, რასაც რეალურად გადაიხდიდით ადგილზე...",
    "about_story_h4": "მარტივი ენა, რეალური ცოდნა",
    "about_story_p4": "არანაირი ჟარგონი ახსნის გარეშე. ამ საიტის ყოველი გზამკვლევი დაწერილია...",
    "about_values_eyebrow": "პრინციპები",
    "about_values_title": "რას გულისხმობს better<span style='color: #ff7a00;'>PC</span>",
    "about_v1_title": "პატიოსანი ფასდადება",
    "about_v1_desc": "ფასები არის სავარაუდო და ასეთადვეა მითითებული. არანაირი გაბერილი რიცხვი, რომ აწყობები შედარებით იაფად გამოჩნდეს.",
    "about_v2_title": "არანაირი რეკლამა, არანაირი პარტნიორობა",
    "about_v2_desc": "betterPC არაფერს გამოიმუშავებს კონკრეტული ბრენდების რეკომენდაციით. არჩევანი ეფუძნება ღირებულებას და ხელმისაწვდომობას.",
    "about_v3_title": "ძველ ტექნიკას მნიშვნელობა აქვს",
    "about_v3_desc": "DDR2 და DDR3 მანქანებს კვლავ შეუძლიათ რეალურ მიზნებს ემსახურონ. მათგან მეტი სარგებლის მიღებაში დახმარება ღირს.",
    "about_v4_title": "თავსებადობა უპირველესად",
    "about_v4_desc": "არაფერი რეკომენდირდება შემოწმების გარეშე. პროცესორის, დედაპლატისა და მეხსიერების თავსებადობა მოწმდება, სანამ ფულს დახარჯავთ.",
    "about_v5_title": "ბერძნული კონტექსტი",
    "about_v5_desc": "ფასები, ხელმისაწვდომობა და ნაწილების რჩევები ეფუძნება ბერძნულ და ევროკავშირის ფართო ბაზარს, არა ამერიკულს.",
    "about_v6_title": "მუდმივი გაუმჯობესება",
    "about_v6_desc": "ნაწილების სიები, ფასები და გზამკვლევები ახლდება ბაზრის ცვლილებებთან ერთად. ეს არ არის ერთხელ შექმნილი და მიტოვებული საიტი.",
    "about_cta_title": "მზად ხართ ასაწყობად?",
    "about_cta_desc": "გამოიყენეთ კონფიგურატორი თქვენი შემდეგი კომპიუტერის ფასის დასათვლელად — სულ ახალი, ბიუჯეტური თუ სრულად ძველი სისტემა.",
    "about_cta_btn_primary": "🛠️ გახსენით PC კონფიგურატორი",
    "services_eyebrow": "სერვისები",
    "services_title": "პერსონალური კომპიუტერის დახმარება ადამიანისგან, რომელმაც იცის, რას აკეთებს.",
    "services_desc": "ფორმატირება, გაწმენდა, განახლებები — უპრობლემოდ, თქვენს რაიონში.",
    "services_s1_title": "კომპიუტერის გაწმენდა",
    "services_s1_desc": "მტვრის მოცილება, თერმოპასტის შეცვლა, შიდა გაწმენდა.",
