    "services_price_note": "💬 ფასი დამოკიდებულია სამუშაოზე — მომწერეთ შეფასებისთვის, სანამ რამეს დავიწყებთ.",
    "services_area": "📍 ვემსახურები ხაიდარისა და ათენის ფართო აუზს. სახლში ვიზიტი ან მოიტანეთ თქვენი კომპიუტერი — რაც თქვენთვის მოსახერხებელია.",
