    "formats_title": "أشكال اللوحة الأم",
    "formats_desc": "تحدد اللوحة الأم المكونات التي تناسب جهازك. اللوحات الأكبر توفر فتحات توسعة أكثر، والأصغر توفر مساحة.",
    "formats_atx_tag": "الحجم الكامل",
    "formats_atx_desc": "المعيار المعتمد لمعظم أجهزة سطح المكتب. فتحات PCIe وفتحات ذاكرة كثيرة، ومساحة للتوسع.",
    "formats_matx_tag": "الحجم المتوسط",
    "formats_matx_desc": "خيار متوازن. أصغر قليلاً من ATX، ويدعم معظم المعالجات وبطاقات التوسعة بسعر أقل.",
    "formats_itx_tag": "مدمج",
    "formats_itx_desc": "بصمة صغيرة لصناديق صغيرة الحجم. محدود بفتحة PCIe واحدة وفتحتَي ذاكرة — لكنه قادر بشكل مذهل.",
    "formats_eatx_tag": "للمحترفين",
    "formats_eatx_desc": "نسخة موسّعة من ATX لمحطات العمل ومنصات HEDT. أقصى توسعة، ودعم معالجَين على بعض اللوحات.",
    "meta_size": "الحجم",
    "meta_voltage": "الجهد الكهربائي",
    "meta_speed": "أقصى سرعة",
    "ram_tag": "الذاكرة",
    "ram_title": "أجيال الذاكرة العشوائية",
    "ram_desc": "تؤثر سرعة وسعة ذاكرة النظام على تعدد المهام، والأحمال الإبداعية، ومعدلات الإطارات في الألعاب.",
    "ram_ddr5_tag": "الجيل الحالي",
    "ram_ddr5_desc": "المعيار الحديث للمنصات الحديثة. عرض نطاق ترددي أعلى وتصحيح أخطاء ECC مدمج. تبدأ المجموعات عادةً من 6000+ ميجا نقلة/ثانية لتحقيق أفضل أداء معالجة.",
    "ram_ddr4_tag": "الجيل السابق",
    "ram_ddr4_desc": "لا تزال مستخدمة على نطاق واسع. بأسعار معقولة، ومتوافقة مع الإعدادات القديمة والاقتصادية. النطاق الأمثل: 16–32 جيجابايت بسرعة 3200–3600 ميجاهرتز.",
    "ram_ddr3_tag": "قديمة",
    "ram_ddr3_desc": "توجد في الأجهزة القديمة. مناسبة للاستخدام المكتبي الأساسي، لكنها عائق أمام متطلبات المعالجة الثقيلة الحديثة.",
    "ram_ddr2_tag": "قديمة جداً",
    "ram_ddr2_desc": "عرض نطاق ترددي محدود جداً وبنية قديمة — مناسبة فقط للحفاظ على الأجهزة الكلاسيكية القديمة.",
    "storage_tag": "التخزين",
    "storage_title": "أنواع التخزين",
    "storage_desc": "المكان الذي يعيش فيه نظام التشغيل يحدد مدى سرعة إحساسك بجهازك. بالنسبة لمعظم الأجهزة، يُعد قرص NVMe SSD الخيار الصحيح لنظام التشغيل.",
    "storage_nvme_tag": "موصى به",
    "storage_nvme_desc": "أقراص M.2 متصلة عبر PCIe. تصل الأجيال الحديثة إلى سرعات استثنائية — شبه فورية عملياً لتحميل نظام التشغيل والتطبيقات.",
    "storage_sata_tag": "اقتصادي",
    "storage_sata_desc": "بشكل 2.5 بوصة أو M.2، محدود بواجهة SATA القديمة. ترقية هائلة مقارنة بأي قرص ميكانيكي دوّار.",
    "storage_hdd_tag": "تخزين كبير السعة",
    "storage_hdd_desc": "قرص ميكانيكي دوّار. تكلفة لكل جيجابايت لا تُضاهى للملفات الكبيرة والمصفوفات والنسخ الاحتياطية — فقط تجنب وضع نظام التشغيل الأساسي هنا.",
    "cpu_tag": "المعالج",
    "cpu_title": "ما يجب معرفته عن المعالجات",
    "cpu_desc": "المعالج هو عقل جهازك. يعتمد الاختيار على نوع الاستخدام: الألعاب تفضل سرعة الساعة، والعمل الإبداعي يفضل عدد الأنوية.",
    "cpu_cores_tag": "عدد الأنوية",
    "cpu_cores_desc": "المزيد من الأنوية يتعامل مع مهام أكثر بسلاسة. يستفيد أكثر رسم الفيديو، والمحاكاة الهندسية، وإعدادات البث الثقيلة.",
    "cpu_clock_tag": "الأداء",
    "cpu_clock_desc": "يُقاس بالجيجاهرتز. السرعات العالية تعظّم المهام أحادية الخيط. تُدار الترددات القصوى قصيرة المدى عبر خطوات التعزيز المدمجة.",
    "cpu_arch_tag": "الجيل",
    "cpu_arch_desc": "زيادات IPC تعني أن المعماريات الأحدث بنفس سرعة الساعة ستتفوق بشكل موثوق على الإصدارات القديمة.",
    "cpu_tdp_tag": "الحرارة",
    "cpu_tdp_desc": "قدرة التصميم الحراري توجّه اختيارك لحلول التبريد. تتطلب المخرجات العالية للطاقة كتل تبريد فعالة وقوية.",
    "gpu_tag": "الرسومات",
    "gpu_title": "بطاقات الرسومات",
    "gpu_desc": "بطاقة الرسومات هي أهم مكون للألعاب والأحمال المرئية. فهي التي ترسم كل إطار تراه على الشاشة.",
    "gpu_vram_tag": "ذاكرة الفيديو",
    "gpu_vram_desc": "تحتفظ ذاكرة الفيديو بأنسجة المعالجة. تتوسع التطبيقات والدقات الحديثة بشكل كبير، مما يجعل السعة الأساسية مهمة للغاية.",
    "gpu_upscale_tag": "تحسين الدقة",
    "gpu_upscale_desc": "تسمح محركات التحجيم الذكية للأجهزة الرسومية بحساب الإعدادات بأبعاد أقل وعرض أهداف ديناميكية أعلى.",
    "gpu_ray_tag": "تتبع الأشعة",
    "gpu_ray_desc": "يحاكي المسارات الفيزيائية الهيكلية لأشعة الضوء. حسابات مذهلة في متطلباتها تحتاج أنوية معجَّلة بواسطة الأجهزة.",
    "gpu_pwr_tag": "استهلاك الطاقة",
    "gpu_pwr_desc": "تسحب مسرّعات الرسومات الثقيلة أحمالاً تشغيلية هائلة. طابق بعناية سعة الخط مع هوامش أمان.",
    "psu_tag_top": "البنية التحتية",
    "psu_title": "الطاقة والتبريد",
    "psu_desc": "أساس نظام مستقر. التزويد النظيف بالطاقة والتبديد المناسب للحرارة يضمنان دورة حياة طويلة للأجهزة.",
    "psu_efficiency_tag": "الكفاءة",
    "psu_efficiency_desc": "تمثل شهادات 80 Plus كفاءة التحويل النظيفة. الشهادة الأعلى تعني حرارة أقل مهدورة.",
    "psu_modularity_tag": "المعيارية",
    "psu_modularity_desc": "الوحدات المعيارية بالكامل تدعم تكوينات قابلة للفصل، مما يعظّم مساحة تدفق الهواء داخل الهياكل الحديثة.",
    "cool_air_tag": "التبريد الهوائي",
    "cool_air_desc": "إعدادات ميكانيكية هيكلية موثوقة للغاية تستخدم أنظمة زعانف معدنية وتشغيلاً مستمراً للمراوح لتشغيل بسيط وطويل الأمد.",
    "cool_liquid_tag": "التبريد السائل",
    "cool_liquid_desc": "دوائر سائلة توجّه الحرارة إلى مصفوفات مبردات كبيرة. مثالية لإدارة الترددات الحاسوبية القوية والذروات المفاجئة بسلاسة.",
    "feat_1_title": "أحدث الأجهزة",
