/**
 * Shared i18n engine for betterPC (index.html, build.html, about.html).
 * Applies translations to every element with a [data-i18n] attribute,
 * persists the chosen language in localStorage, and keeps the
 * #langSelect dropdown in sync across page loads.
 */
(function () {
  function applyLanguage(lang) {
    if (!translations[lang]) lang = 'en';

    document.documentElement.lang = lang;

    document.querySelectorAll('[data-i18n]').forEach((el) => {
      const key = el.getAttribute('data-i18n');
      const value = translations[lang] && translations[lang][key];
      if (value !== undefined) {
        // innerHTML on purpose: some translations contain markup
        // (e.g. <br>, <em>, <span style="...">) or HTML entities.
        el.innerHTML = value;
      }
    });

    localStorage.setItem('selectedLanguage', lang);

    const select = document.getElementById('langSelect');
    if (select) select.value = lang;

    // Let page-specific scripts (e.g. build.html's live calculator)
    // react to a language change without duplicating the i18n engine.
    document.dispatchEvent(
      new CustomEvent('i18n:languagechange', { detail: { lang } })
    );
  }

  function init() {
    const saved = localStorage.getItem('selectedLanguage') || 'en';
    applyLanguage(saved);

    const select = document.getElementById('langSelect');
    if (select) {
      select.addEventListener('change', (e) => applyLanguage(e.target.value));
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  // Exposed in case a page needs to trigger a re-translate manually
  // (e.g. after injecting dynamic content).
  window.applyLanguage = applyLanguage;
})();
